steps.sql:
-- browse each publisher's STAC index and read what each dataset ANSWERS (OSI semantics);
-- the catalogue is generic — nothing in it is tailored to data centres.
SELECT id, collection,
       json_extract_string(properties,'$.semantics.answers[0]') AS answers
FROM nls.catalog.datasets;

-- NDVI = (NIR - Red) / (NIR + Red) over the site
SELECT avg((band_2 - band_1)/(band_2 + band_1)) AS ndvi
FROM read_raquet('Copernicus → ndvi'), grid;
